  "query": "select r.rolname, r.rolsuper, r.rolinherit, r.rolcreaterole, r.rolcreatedb, r.rolcanlogin, r.rolreplication, r.rolbypassrls, coalesce(array_agg(distinct m.rolname) filter (where m.rolname is not null), '{}'::name[]) as member_of from pg_roles r left join pg_auth_members am on am.member=r.oid left join pg_roles m on m.oid=am.roleid where r.rolname not like 'pg_%' group by r.rolname,r.rolsuper,r.rolinherit,r.rolcreaterole,r.rolcreatedb,r.rolcanlogin,r.rolreplication,r.rolbypassrls order by r.rolname; 

select n.nspname, c.relname, c.relkind, grantee, privilege_type from information_schema.role_table_grants g join pg_class c on c.relname=g.table_name join pg_namespace n on n.nspname=g.table_schema where g.table_schema not in ('pg_catalog','information_schema') and grantee in ('anon','authenticated','service_role','public') order by n.nspname,c.relname,grantee,privilege_type;

select defaclnamespace::regnamespace as schema_name, defaclrole::regrole as owner_role, defaclobjtype, defaclacl from pg_default_acl order by 1,2,3;"
}

